package com.idfc.ai.runbook.repository;
import java.nio.file.*; import java.io.*; import org.springframework.stereotype.Component;
@Component public class LocalRepositoryWorkspaceProvider implements RepositoryWorkspaceProvider { public RepositoryWorkspace prepare(String localPath,String expected){ try { Path path=Path.of(localPath).toRealPath(); if(!Files.isDirectory(path)) throw new IllegalArgumentException("RUNBOOK_REPOSITORY_INVALID"); Process p=new ProcessBuilder("git","rev-parse","HEAD").directory(path.toFile()).start(); String sha=new String(p.getInputStream().readAllBytes()).trim(); if(p.waitFor()!=0) throw new IllegalArgumentException("RUNBOOK_REPOSITORY_INVALID: not a Git checkout"); if(expected!=null&&!expected.isBlank()&&!sha.startsWith(expected)) throw new IllegalArgumentException("RUNBOOK_COMMIT_MISMATCH"); return new RepositoryWorkspace(path,sha); } catch(IOException|InterruptedException e){Thread.currentThread().interrupt();throw new IllegalArgumentException("RUNBOOK_REPOSITORY_INVALID",e);} } }
